-- 쿠폰 코드. 생성 API 없이 운영자가 SQL로 직접 넣으므로 생성·수정 시각에 기본값을 둔다.
-- 코드는 대문자로 저장하고 입력은 대문자로 바꿔 대조한다. 입력 기한이 비어 있으면 기한 없이 사용할 수 있고, 기한이 된 시각부터는 사용할 수 없다.
CREATE TABLE "coupons" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "code" VARCHAR(50) NOT NULL,
    "ai_trial_count" INTEGER NOT NULL,
    "redeemable_until" TIMESTAMP WITH TIME ZONE,
    "created_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "uk_coupons_code" UNIQUE ("code"),
    CONSTRAINT "chk_coupons_code_uppercase" CHECK ("code" = UPPER(BTRIM("code")) AND "code" <> ''),
    CONSTRAINT "chk_coupons_ai_trial_count" CHECK ("ai_trial_count" > 0)
);

-- 쿠폰 사용 기록. 한 사용자는 같은 쿠폰을 한 번만 쓴다. ai_trial_count는 사용 당시 지급한 횟수다.
CREATE TABLE "coupon_redemptions" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "coupon_id" BIGINT NOT NULL,
    "user_id" BIGINT NOT NULL,
    "ai_trial_count" INTEGER NOT NULL,
    "created_at" TIMESTAMP NOT NULL,
    CONSTRAINT "uk_coupon_redemptions_coupon_id_user_id" UNIQUE ("coupon_id", "user_id")
);
